(function(root){
const departments=[
{id:'admin',name:'Admin & quick documents',lead:'Iris + Nova',price:100,unit:5,measure:'routine document or admin requests',examples:['Quick PDF, letter, presentation outline or meeting brief','Document collection, formatting and task reminders'],inputs:'The purpose, source facts, required format and deadline. Urgent delivery is confirmed before acceptance.'},
{id:'creative',name:'Creative studio',lead:'Nova',price:150,unit:4,measure:'standard creative deliverables',examples:['Branded images, flyers or slide decks','Short video scripts and design adaptations'],inputs:'Brand assets, approved claims and deliverable specifications. Video rendering scope is agreed in advance.'},
{id:'marketing',name:'Marketing & publishing',lead:'Leo',price:200,unit:8,measure:'scheduled post placements across up to 2 channels',examples:['A content plan, captions and simple branded visuals','Publishing confirmation and a factual nightly activity report'],inputs:'Authorized page access, brand materials and approved offers. Each post to each channel counts as one placement; reel production is scoped within the agreed work plan.'},
{id:'customer',name:'Customer desk',lead:'Maya + Iris',price:150,unit:150,measure:'supported inbound conversations on 1 agreed channel',examples:['Approved FAQ responses and lead qualification','Handover and a daily enquiry summary'],inputs:'Approved FAQs, business hours, routing rules and authorized channel access. This is planned managed support; client-owned bots are scoped separately.'},
{id:'finance',name:'Finance & bookkeeping support',lead:'Ledger',price:150,unit:40,measure:'sales or expense records prepared',examples:['Organized sales and expense records with a summary','Invoice drafts and approved invoice-email workflows'],inputs:'Accurate sales records, customer billing details, authorized sender access and approval rules. Tax filings, audit and professional sign-off require separately agreed scope.'},
{id:'research',name:'Research & meeting support',lead:'Sage + Orion',price:100,unit:2,measure:'focused research or meeting briefs',examples:['A concise, source-backed business or competitor brief','Meeting preparation, key questions and an executive summary'],inputs:'The topic, context, source material and deadline. Time-sensitive requests need an accepted turnaround.'},
{id:'technology',name:'Website care & automation',lead:'Atlas + Orion',price:150,unit:2,measure:'scoped small maintenance or workflow requests',examples:['Content updates, checks or a small integration adjustment','Maintenance summaries and issue triage'],inputs:'An existing website or workflow, authorized access and a bounded change request. New builds and large integrations need separate scoping.'}
];
const levels=[{id:'essential',name:'Essential',multiplier:1,description:'A focused monthly work allowance.'},{id:'growth',name:'Growth',multiplier:2,description:'Twice the listed allowance.'},{id:'extended',name:'Extended',multiplier:3,description:'Three times the listed allowance.'}];
function calculate(ids,levelId){const level=levels.find(x=>x.id===levelId);if(!level)throw new Error('Unknown work level');const selected=departments.filter(x=>new Set(ids).has(x.id));const total=selected.reduce((n,d)=>n+d.price,0)*level.multiplier;return {selected,level,total,weekly:total/4,allowances:selected.map(d=>`${d.unit*level.multiplier} ${d.measure}`)}}
const api={departments,levels,calculate};root.OfficeModel=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window==='undefined'?globalThis:window);
